const cfg = $('Configuração — Edite Aqui').first().json;
const TEMAS = [
  { id: 'ramal-remoto', titulo: 'Ramal em qualquer lugar', fatos: 'PABX IP na nuvem (ConnectX). O ramal funciona no computador ou no celular, com o mesmo número, de casa, da filial ou da rua. Sem equipamento para manter no escritório.' },
  { id: 'fixo-movel', titulo: 'Ligações por valor fixo', fatos: 'Ligações ilimitadas para fixos e celulares por valor fixo, ligações internas sem custo entre a equipe e número fixo de outras cidades.' },
  { id: 'slack-zoho', titulo: 'Slack + Zoho Desk', fatos: 'Integração que transforma conversas do Slack em tickets e comentários no Zoho Desk. Conversas normais ficam em um ticket por canal por dia; uma thread abre um ticket próprio com o título da mensagem original. Imagens viram anexos.' },
  { id: 'monitoramento', titulo: 'Monitoramento 24/7', fatos: 'Monitoramento contínuo de conectividade, serviços e servidores, para agir antes de o cliente perceber o problema.' },
  { id: 'consultoria', titulo: 'Consultoria de TI', fatos: 'Visão externa, identificação de problemas ocultos e tempo devolvido para a equipe.' },
  { id: 'integracoes-crm', titulo: 'CRM e mensagens corporativas', fatos: 'Integrações entre CRMs e aplicativos de mensagens corporativas, sem copiar e colar entre sistemas.' },
  { id: 'portaria', titulo: 'Portaria remota', fatos: 'Atendimento e liberação de acesso à distância integrados ao PABX IP.' },
  { id: 'sistemas', titulo: 'Sistemas e aplicativos sob medida', fatos: 'Desenvolvimento de sites, sistemas web, aplicativos e integrações construídos junto com a operação do cliente.' }
];

// Tema: o personalizado da configuração ou um sorteio que evita repetir o último.
// (Em execuções manuais o n8n não grava o histórico; por isso o sorteio é aleatório.)
const sd = $getWorkflowStaticData('global');
const forcado = String(cfg.TEMA_PERSONALIZADO ?? '').trim();
let tema;
if (forcado) {
  tema = { id: 'personalizado', titulo: forcado, fatos: String(cfg.FATOS_PERSONALIZADOS || forcado) };
} else {
  const opcoes = TEMAS.filter(x => x.id !== sd.ultimoTema);
  tema = opcoes[Math.floor(Math.random() * opcoes.length)];
  sd.ultimoTema = tema.id;
}
const ANGULOS = [
  'abrir com uma pergunta direta ao leitor sobre um problema do dia a dia',
  'abrir descrevendo uma situação comum de uma empresa antes de resolver o problema',
  'abrir com o benefício principal em uma frase curta e objetiva',
  'abrir com um contraste simples entre como era antes e como pode ser agora (sem inventar números)',
  'abrir com uma afirmação firme que corrija uma ideia errada sobre o assunto'
];
const angulo = ANGULOS[Math.floor(Math.random() * ANGULOS.length)];
const recentes = Array.isArray(sd.recentes) ? sd.recentes : [];
const site = String((cfg.SITE_URL ?? 'https://conectxip.com')).replace(/\/+$/, '');
return [{ json: { tema, angulo, recentes, site, imagem: String(cfg.SOCIAL_IMAGE_URL ?? '').trim() } }];

const cfg = $('Configuração — Edite Aqui').first().json;
const base = $('Escolhe Tema (rodízio)').first().json;
const { tema, site, imagem } = base;
const resp = $input.first().json;

// 1) Tenta ler o JSON gerado pela IA (tolera texto antes/depois do JSON)
let ia = null, iaMotivo = '';
try {
  const ch = (resp.choices || [])[0] || {};
  const bruto = String((ch.message && ch.message.content) || '').trim();
  if (!bruto) {
    const e = resp.error;
    iaMotivo = String((e && (e.message || e.description)) || (typeof e === 'string' ? e : '') || resp.message || (ch.finish_reason ? 'resposta vazia (' + ch.finish_reason + ')' : 'resposta vazia da API do Groq')).slice(0, 200);
  } else {
    const j = JSON.parse(bruto.slice(bruto.indexOf('{'), bruto.lastIndexOf('}') + 1));
    if (j && j.linkedin && j.facebook && j.instagram) ia = j;
    else iaMotivo = 'o JSON da IA veio sem os campos esperados';
  }
} catch (e) { iaMotivo = 'não foi possível ler a resposta da IA: ' + String(e.message).slice(0, 100); }

// 2) Plano B sem IA: texto fixo e seguro, só com os fatos do tema
const cta = 'Conheça a ConectPbx.';
const plano = {
  linkedin: `${tema.titulo}\n\n${tema.fatos}\n\n${cta}`,
  facebook: `${tema.titulo}: ${tema.fatos} ${cta}`,
  instagram: `${tema.titulo}\n\n${tema.fatos}\n\n${cta}`,
  hashtags: ['telefoniaIP', 'PABX', 'TI', 'ConectPbx'],
  imagem: `Modern flat illustration, square, dark navy background with orange accents, abstract technology scene about: ${tema.titulo}. No text, no letters, no logos, no people.`
};
const src = ia || plano;
const fonte = ia ? 'ia' : 'plano_b';
if (ia) {
  const sd = $getWorkflowStaticData('global');
  sd.recentes = [...(Array.isArray(sd.recentes) ? sd.recentes : []), String(ia.linkedin).replace(/\s+/g, ' ').slice(0, 90)].slice(-6);
}

const tags = (Array.isArray(src.hashtags) ? src.hashtags : plano.hashtags)
  .map(t => String(t).replace(/[^\p{L}\p{N}_]/gu, '')).filter(Boolean).slice(0, 6)
  .map(t => '#' + t).join(' ');

const url = rede => `${site}/?utm_source=${rede}&utm_medium=social&utm_campaign=${encodeURIComponent(tema.id)}`;
const corta = (s, n) => { s = String(s); return s.length <= n ? s : s.slice(0, n - 1).trimEnd() + '…'; };

const linkedin  = corta(`${src.linkedin}\n\n${url('linkedin')}\n\n${tags}`, 2900);
const facebook  = corta(`${src.facebook}\n\n${tags}`, 1800);
const instagram = corta(`${src.instagram}\n\nLink na bio.\n\n${tags}`, 2100);

return [{ json: {
  tema, fonte, iaMotivo: ia ? '' : iaMotivo, imagem, tags,
  imagemPrompt: String(src.imagem || plano.imagem).slice(0, 600),
  gerarImagem: String(cfg.GERAR_IMAGEM ?? 'true').toLowerCase() === 'true',
  imgbbDias: Math.min(180, Math.max(1, Number(cfg.IMGBB_EXPIRA_DIAS) || 30)),
  linkedin, facebook, instagram,
  facebookLink: url('facebook'),
  temImagem: /^https:\/\//i.test(imagem),
  aprovacao: String(cfg.SOCIAL_APPROVAL ?? 'true').toLowerCase() === 'true'
} }];

const get = nome => { try { return $(nome).first().json; } catch (e) { return null; } };
const ok = (j, campo) => !!(j && !j.error && !j.errorMessage && (campo ? j[campo] : true));
const li = get('LinkedIn — Publicar');
const fb = get('Facebook — Publicar Foto') || get('Facebook — Publicar na Página');
const igc = get('Instagram — Criar Mídia');
const igp = get('Instagram — Publicar');
const post = get('Define Imagem Final');
const prep = get('LinkedIn — Preparar Texto');
const limg = get('LinkedIn — Monta Post com Imagem');

const linhas = [
  `LinkedIn: ${(prep && prep.pular) ? 'FALHOU (' + prep.motivo + ')' : (ok(li) ? 'publicado' + (limg && limg.semImagemLinkedin ? ' sem imagem (' + limg.avisoImagemLinkedin + ')' : '') : 'FALHOU')}`,
  `Facebook: ${ok(fb, 'id') ? 'publicado' : 'FALHOU'}`,
  `Instagram: ${post && !post.temImagem ? 'ignorado (sem imagem' + (post.imagemAviso ? ': ' + post.imagemAviso : '') + ')' : (ok(igc, 'id') && ok(igp, 'id') ? 'publicado' : 'FALHOU')}`
];
const houveFalha = linhas.some(l => l.includes('FALHOU'));
const html = `<div style="font-family:Arial,sans-serif;color:#0c1729"><p><b>${houveFalha ? 'Alguma rede falhou' : 'Divulgação concluída'}</b>: ${String(post?.tema?.titulo || '')}</p><p style="white-space:pre-line">${linhas.join('\n')}</p>${houveFalha ? '<p style="color:#667;font-size:12px">Confira a execução no n8n para ver o erro de cada rede.</p>' : ''}</div>`;
return [{ json: { tema: post?.tema?.titulo, fonte: post?.fonte, resumo: linhas.join('\n'), houveFalha, html } }];

const cfg = $('Configuração — Edite Aqui').first().json;
// Texto no formato do LinkedIn ("little text"): caracteres reservados precisam de barra.
// O "#" fica sem escape para as hashtags funcionarem.
const post = $('Define Imagem Final').first().json;
const escapa = s => String(s).replace(/([\\|{}@\[\]()<>*_~])/g, '\\$1');
let author = String(cfg.LINKEDIN_AUTHOR_URN ?? '').trim();
if (!author) {
  try { const me = $('LinkedIn — Descobrir Meu ID').first().json; if (me && me.sub) author = 'urn:li:person:' + me.sub; } catch (e) {}
}
if (!/^urn:li:(person|organization):[A-Za-z0-9_-]+$/.test(author)) {
  // Não derruba o fluxo: o LinkedIn é pulado e o motivo aparece aqui e no e-mail de resultado.
  return [{ json: { pular: true, motivo: 'Autor do LinkedIn indefinido. Confira a credencial (escopos openid profile w_member_social) ou preencha LINKEDIN_AUTHOR_URN no nó Configuração — Edite Aqui.' } }];
}
return [{ json: {
  author,
  temImagem: !!post.temImagem,
  imagem: post.imagem || '',
  initBody: { initializeUploadRequest: { owner: author } },
  version: String(cfg.LINKEDIN_API_VERSION ?? '202608'),
  body: {
    author,
    commentary: escapa(post.linkedin).slice(0, 3000),
    visibility: 'PUBLIC',
    distribution: { feedDistribution: 'MAIN_FEED', targetEntities: [], thirdPartyDistributionChannels: [] },
    lifecycleState: 'PUBLISHED',
    isReshareDisabledByAuthor: false
  }
} }];

const post = $('Define Imagem Final').first().json;
const h = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>');
const bloco = (titulo, texto) => `<h3 style="margin:18px 0 6px;font-size:15px">${titulo}</h3><div style="padding:12px 14px;background:#f4f6fa;border-radius:8px;font-size:14px;line-height:1.5">${h(texto)}</div>`;
const link = $execution.resumeUrl;
const html = `<div style="font-family:Arial,sans-serif;max-width:640px;color:#0c1729">
<p style="font-size:15px">Post para aprovar: <b>${h(post.tema.titulo)}</b> <span style="color:#667">(texto: ${post.fonte === 'ia' ? 'gerado por IA' : 'TEXTO DE RESERVA, a IA falhou: ' + h(post.iaMotivo || 'motivo desconhecido')})</span></p>
${post.temImagem ? `<img src="${post.imagem}" alt="Imagem do post" style="max-width:100%;width:420px;border-radius:8px;margin:8px 0"><p style="font-size:12px;color:#667">Imagem: ${post.imagemOrigem === 'cloudflare' ? 'gerada pelo FLUX (Cloudflare)' : 'imagem fixa de reserva'}</p><p style="font-size:11px;color:#889">Prompt da imagem: ${h(post.imagemPrompt || '')}</p>` : `<p style="color:#a60">Sem imagem${post.imagemAviso ? ' (' + h(post.imagemAviso) + ')' : ''}. O Instagram será ignorado.</p>`}${bloco('LinkedIn', post.linkedin)}${bloco('Facebook', post.facebook)}${bloco('Instagram' + (post.temImagem ? '' : ' (sem imagem, será ignorado)'), post.instagram)}
<p style="margin:26px 0 8px"><a href="${link}" style="background:#e4570f;color:#fff;padding:12px 22px;border-radius:8px;text-decoration:none;font-weight:bold">Aprovar e publicar</a></p>
<p style="font-size:12px;color:#667">Para não publicar, ignore este e-mail. O rascunho expira em 48 horas. Não encaminhe este e-mail: quem tiver o link consegue aprovar.</p></div>`;
return [{ json: { assunto: `[Aprovar post] ${post.tema.titulo}`, html } }];

// EDITE AQUI: todas as configurações do workflow ficam neste nó (não precisa de "Variables" do n8n).
const CONFIG = {
  // Site e conteúdo
  SITE_URL: 'https://conectxip.com',
  SOCIAL_IMAGE_URL: '',            // imagem fixa de reserva, usada se a geração falhar (vazio = sem reserva)
  TEMA_PERSONALIZADO: '',          // opcional: assunto do post (vazio = rodízio automático dos temas)
  FATOS_PERSONALIZADOS: '',        // opcional: fatos reais sobre o assunto (a IA só usa o que estiver aqui)
  // IA de texto: Groq (chave em console.groq.com/keys)
  GROQ_MODEL: 'llama-3.3-70b-versatile',   // troque se o Groq descontinuar o modelo (veja console.groq.com/docs/models)

  // Imagens geradas pelo Cloudflare Workers AI (FLUX.1-schnell) e hospedadas no imgbb
  GERAR_IMAGEM: 'true',            // 'false' usa só a imagem fixa de SOCIAL_IMAGE_URL
  CLOUDFLARE_ACCOUNT_ID: '',       // ID da conta (32 caracteres), no painel da Cloudflare
  CLOUDFLARE_IMAGE_MODEL: '@cf/black-forest-labs/flux-1-schnell',
  IMGBB_EXPIRA_DIAS: '30',         // de 1 a 180

  // Aprovação por e-mail (Gmail)
  SOCIAL_APPROVAL: 'true',         // 'true' pede aprovação; 'false' publica direto
  SOCIAL_APPROVER_EMAIL: 'seu-email@gmail.com',

  // LinkedIn
  LINKEDIN_AUTHOR_URN: '',         // vazio = usa o seu perfil automaticamente; ou urn:li:organization:NNNN
  LINKEDIN_API_VERSION: '202608',

  // Facebook e Instagram (IDs do Graph API)
  FACEBOOK_PAGE_ID: '',
  INSTAGRAM_USER_ID: ''
};
return [{ json: CONFIG }];

const r = $input.first().json || {};

// Resposta da API REST da Cloudflare: { result: { image: "<base64>" }, success: true }
const img = (r.result && r.result.image) || r.image || '';
if (typeof img === 'string' && img.length > 100) {
  const limpo = img.replace(/^data:image\/[a-z]+;base64,/i, '');
  const mime = limpo.startsWith('iVBOR') ? 'image/png' : (limpo.startsWith('UklGR') ? 'image/webp' : 'image/jpeg');
  return [{ json: { semImagem: false, b64: limpo, mime } }];
}

const erro = Array.isArray(r.errors) && r.errors[0] ? (r.errors[0].message || JSON.stringify(r.errors[0])) : '';
return [{ json: { semImagem: true, motivo: String(erro || (r.error && (r.error.message || r.error)) || r.message || 'A Cloudflare não devolveu imagem').slice(0, 300) } }];

const base = { ...$('Monta Posts').first().json };
try { const mpi = $('Monta Prompt de Imagem').first().json; base.imagemPrompt = mpi.imagemPrompt; base.promptImagemOrigem = mpi.promptImagemOrigem; } catch (e) {}
let url = '', origem = 'nenhuma', motivo = '';
try {
  const r = $('imgbb — Hospedar Imagem').first().json;
  const u = r && r.data && r.data.url;
  if (/^https:\/\//i.test(String(u || ''))) { url = u; origem = 'cloudflare'; }
  else motivo = 'imgbb não devolveu URL';
} catch (e) {}
if (!url) {
  try {
    const g = $('Extrai Imagem').first().json;
    if (g && g.semImagem) motivo = 'Imagem: ' + g.motivo;
  } catch (e) {}
  url = String(base.imagem || '').trim();
  if (/^https:\/\//i.test(url)) origem = 'fixa';
}
return [{ json: { ...base, imagem: url, temImagem: /^https:\/\//i.test(url), imagemOrigem: origem, imagemAviso: motivo } }];

const cfg = $('Configuração — Edite Aqui').first().json;
const { tema, angulo, recentes } = $input.first().json;

const prompt = `Você escreve posts de redes sociais em português do Brasil para a ConectPbx, empresa de telefonia IP e TI de São Paulo (PABX IP ConnectX, monitoramento, consultoria, integrações e desenvolvimento).
Tema do post: ${tema.titulo}
Ângulo de abertura deste post: ${angulo || 'livre'}
Posts recentes (não repita aberturas, frases nem estrutura): ${(recentes && recentes.length) ? recentes.join(' | ') : 'nenhum'}
Fatos permitidos (use apenas isto): ${tema.fatos}

Regras:
- Não invente números, preços, prazos, clientes, prêmios ou depoimentos.
- Tom profissional e direto, sem exageros, sem emojis em excesso (no máximo 2).
- Cada versão deve terminar convidando a conhecer o site, sem escrever o endereço (ele será adicionado depois).
- LinkedIn: 500 a 900 caracteres, com abertura que chame atenção.
- Facebook: 250 a 450 caracteres.
- Instagram: 300 a 600 caracteres.
- hashtags: de 4 a 6, sem espaços, sem "#" no início de cada item.
- imagem: descrição visual em inglês, de 1 a 2 frases, para gerar uma ilustração quadrada moderna do tema. Sem texto, sem letras, sem logotipos, sem rostos de pessoas reais. Paleta azul-marinho escuro com detalhes em laranja.

Responda somente com JSON válido neste formato, sem texto fora dele:
{"linkedin":"...","facebook":"...","instagram":"...","hashtags":["...","..."],"imagem":"..."}`;

const requestUrl = 'https://api.groq.com/openai/v1/chat/completions';
const modelo = String(cfg.GROQ_MODEL || 'llama-3.3-70b-versatile').trim();
return [{ json: {
  tema,
  requestUrl,
  requestBody: {
    model: modelo,
    messages: [
      { role: 'system', content: 'Você é um redator de redes sociais. Responda sempre e somente com JSON válido.' },
      { role: 'user', content: prompt }
    ],
    max_completion_tokens: 2500,
    temperature: 0.9,
    response_format: { type: 'json_object' }
  }
} }];

const cfg = $('Configuração — Edite Aqui').first().json;
const b = $input.first().json;
const conta = String(cfg.CLOUDFLARE_ACCOUNT_ID || '').trim();
const modelo = String(cfg.CLOUDFLARE_IMAGE_MODEL || '@cf/black-forest-labs/flux-1-schnell').trim();
return [{ json: { ...b,
  cfUrl: `https://api.cloudflare.com/client/v4/accounts/${conta}/ai/run/${modelo}`,
  cfBody: { prompt: String(b.imagemPrompt).slice(0, 2000), steps: 6 }
} }];

const prep = $('LinkedIn — Preparar Texto').first().json;
const put = $input.first().json || {};
let urn = '';
try { urn = String($('LinkedIn — Iniciar Upload').first().json.value.image || ''); } catch (e) {}
let baixou = true;
try { const d = $('LinkedIn — Baixar Imagem').first(); baixou = !!(d.binary && d.binary.data); } catch (e) { baixou = false; }
const falhou = !!(put.error || put.errorMessage);
const body = { ...prep.body };
let aviso = '';
if (urn.startsWith('urn:li:image:') && baixou && !falhou) {
  body.content = { media: { id: urn, altText: 'Ilustração do tema do post' } };
} else {
  aviso = !urn ? 'LinkedIn não iniciou o upload da imagem' : (!baixou ? 'não foi possível baixar a imagem' : 'o envio da imagem ao LinkedIn falhou');
}
return [{ json: { ...prep, body, semImagemLinkedin: !!aviso, avisoImagemLinkedin: aviso } }];

const cfg = $('Configuração — Edite Aqui').first().json;
const b = $input.first().json;
const resumo = String(b.linkedin || '').replace(/\s+/g, ' ').slice(0, 900);

const prompt = `You are the art director for a B2B telecom and IT company (cloud PBX, monitoring, integrations, custom software). Write ONE detailed image-generation prompt, in English, for a text-to-image model (FLUX), to illustrate the social media post below.

Post theme: ${b.tema.titulo}
Post text (Portuguese): ${resumo}

The prompt must have 90 to 150 words and must describe, in this order:
1. Main subject: one concrete visual metaphor that expresses the CENTRAL IDEA of this exact post (for example: a softphone on a laptop and a smartphone linked by glowing lines to a cloud; a monitoring dashboard with an uptime line and status lights; two app windows exchanging data through connected nodes). Do not use generic abstract shapes.
2. Composition: square 1:1, one clear focal point near the center, balanced layout, generous negative space, clean uncluttered background.
3. Style: premium editorial technology illustration, modern isometric or flat vector with soft gradients, subtle depth and fine highlights, sharp clean edges, professional corporate look.
4. Color palette: deep navy blue background (#0C1729), vivid orange accents (#E4570F), white and soft cyan highlights.
5. Lighting and mood: soft rim light, gentle glow around the connections, confident, reliable, modern.
6. Hard constraints at the end: no text, no letters, no numbers, no logos, no watermark, no human faces, no photo-realistic people, no clutter.

Answer only with valid JSON in this format, with no text outside it:
{"prompt":"..."}`;

const requestUrl = 'https://api.groq.com/openai/v1/chat/completions';
const modelo = String(cfg.GROQ_MODEL || 'llama-3.3-70b-versatile').trim();
return [{ json: { ...b, requestUrl, requestBody: {
  model: modelo,
    messages: [
    { role: 'system', content: 'You are an art director. Answer only with valid JSON.' },
    { role: 'user', content: prompt }
  ],
  max_completion_tokens: 1200,
    temperature: 0.9,
  response_format: { type: 'json_object' }
} } }];

const base = $('Monta Posts').first().json;
const r = $input.first().json || {};
let p = '';
try {
  const t = String(((r.choices || [])[0] || {}).message?.content || '');
  p = String(JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)).prompt || '').trim();
} catch (e) {}
const ok = p.length >= 60;
return [{ json: { ...base, imagemPrompt: ok ? p.slice(0, 1800) : base.imagemPrompt, promptImagemOrigem: ok ? 'direcao_de_arte' : 'padrao' } }];
